input.command:
cat > /tmp/proxy.py <<'EOF'
import http.server, http.client, sys, json

class P(http.server.BaseHTTPRequestHandler):
    def _proxy(self, method):
        length = int(self.headers.get('Content-Length', 0))
        body = self.rfile.read(length) if length else b''
        print(f"=== {method} {self.path}", flush=True)
        for k, v in self.headers.items():
            print(f"  {k}: {v}", flush=True)
        print(f"  BODY: {body.decode('utf-8', errors='replace')}", flush=True)
        # Forward to real API
        conn = http.client.HTTPSConnection("app.daytona.io", 443, timeout=30)
        headers = {k: v for k, v in self.headers.items() if k.lower() not in ('host',)}
        conn.request(method, self.path, body, headers)
        resp = conn.getresponse()
        resp_body = resp.read()
        print(f"  RESPONSE STATUS: {resp.status}", flush=True)
        print(f"  RESPONSE BODY: {resp_body.decode('utf-8', errors='replace')[:500]}", flush=True)
        print(flush=True)
        self.send_response(resp.status)
        for k, v in resp.getheaders():
            if k.lower() not in ('transfer-encoding', 'connection'):
                self.send_header(k, v)
        self.send_header('Content-Length', str(len(resp_body)))
        self.end_headers()
        self.wfile.write(resp_body)
    def do_GET(self): self._proxy('GET')
    def do_POST(self): self._proxy('POST')
    def do_DELETE(self): self._proxy('DELETE')
    def do_PUT(self): self._proxy('PUT')
    def do_PATCH(self): self._proxy('PATCH')
    def log_message(self, *a, **k): pass

print("Starting proxy on 8088...", flush=True)
http.server.HTTPServer(('127.0.0.1', 8088), P).serve_forever()
EOF
echo "Wrote proxy script"

